		GenerationID:    generationID,
		Commit:          header.Commit,
		Tree:            header.Tree,
		Files:           len(files),
		Symbols:         counts.Symbols,
		Relations:       counts.Relations,
		ReverseEdges:    counts.Relations,
		Warnings:        len(header.Warnings),
		PartialFailures: len(header.PartialFailures),
